// @ts-expect-error The OpenNext worker is generated by the Cloudflare build.
import handler from "./.open-next/worker.js";

type Bindings = {
  EVENT_SYNC_TOKEN?: string;
  WORKER_SELF_REFERENCE: { fetch(request: Request): Promise<Response> };
};

const worker = {
  fetch: handler.fetch,
  async scheduled(_controller: { cron: string; scheduledTime: number }, env: Bindings) {
    if (!env.EVENT_SYNC_TOKEN) throw new Error("Configure the EVENT_SYNC_TOKEN Worker secret before enabling the event schedule.");
    const response = await env.WORKER_SELF_REFERENCE.fetch(new Request("https://finland-experience-platform/api/cron/events", {
      method: "POST",
      headers: { Authorization: `Bearer ${env.EVENT_SYNC_TOKEN}` },
    }));
    if (!response.ok) throw new Error(`Event sync returned HTTP ${response.status}.`);
  },
};

export default worker;
